<template><div class="app-container"><el-alert v-if="access" type="warning" :closable="false" title="仅管理平台内授权记录，未连接真实门禁设备；记录有效不代表现场设备已生效。"/>
<div v-else class="mb8"><el-tag>人员 {{stats.total||0}}</el-tag> <el-tag type="success">在职 {{stats.active||0}}</el-tag> <el-tag type="info">离职 {{stats.departed||0}}</el-tag></div>
<el-form inline><template v-if="!access"><el-input v-model="keyword" placeholder="姓名或工号" style="width:180px"/><el-select v-model="status" clearable placeholder="状态" style="width:130px"><el-option label="在职" value="ACTIVE"/><el-option label="离职" value="LEFT"/></el-select></template><el-button @click="page=1;load()">查询</el-button><el-button type="primary" @click="edit()">{{access?'新增门禁记录':'补录档案'}}</el-button><el-button v-if="!access" v-hasPermi="['biz:personnel:export']" @click="exportData">导出CSV</el-button></el-form>
<el-table :data="rows" v-loading="loading"><el-table-column prop="real_name" label="姓名"/><el-table-column v-if="!access" prop="employee_no" label="工号"/><el-table-column v-if="!access" prop="job_title" label="岗位"/><el-table-column v-if="!access" prop="contact_phone" label="电话"/><el-table-column v-if="access" prop="device_code" label="门禁点编号"/><el-table-column v-if="access" label="设备同步"><template #default>未连接设备</template></el-table-column><el-table-column label="记录状态"><template #default="{row}">{{states[access?row.record_state:row.status]||row.status}}</template></el-table-column><el-table-column v-if="access" prop="valid_to" label="有效期截止"/><el-table-column label="操作" width="300"><template #default="{row}"><el-button link @click="view(row)">详情与轨迹</el-button><el-button link v-if="access||row.status==='ACTIVE'" @click="edit(row)">修改</el-button><el-button link type="danger" v-if="!access&&row.status==='ACTIVE'" @click="change(row)">离职</el-button><el-button link type="danger" v-if="access&&row.status==='ACTIVE'" @click="change(row)">撤销</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="page" v-model:limit="size" @pagination="load"/>
<el-dialog v-model="visible" :title="access?'平台门禁授权记录':'人员档案'" width="560px"><el-form label-width="110px"><el-form-item v-if="!form.id||access" label="关联员工账号"><el-select v-model="form.userId" filterable :remote="access" :remote-method="searchPeople" placeholder="输入姓名、工号或账号编号搜索" :disabled="!!form.id"><el-option v-for="p in candidates" :key="p.user_id" :label="`${p.real_name||p.nick_name}（${p.user_id}）`" :value="p.user_id"/></el-select></el-form-item><template v-if="access"><el-form-item label="门禁点编号"><el-input v-model="form.deviceCode" :disabled="!!form.id" maxlength="80"/></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="form.validFrom" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="form.validTo" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></template><template v-else><el-form-item v-for="(label,key) in fields" :key="key" :label="label"><el-input v-model="form[key]" :maxlength="key==='contactPhone'?30:key==='employeeNo'?40:key==='jobTitle'?80:50"/></el-form-item><el-alert v-if="!form.id" title="仅补录已获本企业归属但缺失档案的账号；新员工请先走员工入驻审核。" type="info" :closable="false"/></template><el-form-item label="变更原因"><el-input v-model="form.reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button :loading="saving" type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="historyVisible" title="详情与变更轨迹" width="750px"><el-descriptions :column="2" border><el-descriptions-item v-for="(value,key) in selected" :key="key" :label="labels[key]||key">{{states[value]||value}}</el-descriptions-item></el-descriptions><el-table :data="history"><el-table-column prop="action" label="操作"/><el-table-column prop="reason" label="原因"/><el-table-column prop="operator_id" label="操作人"/><el-table-column prop="create_time" label="时间"/></el-table></el-dialog>
</div></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const route=useRoute(),access=computed(()=>route.path.endsWith('access-records')),rows=ref([]),stats=ref({}),keyword=ref(''),status=ref(''),page=ref(1),size=ref(20),total=ref(0),loading=ref(false),saving=ref(false),visible=ref(false),historyVisible=ref(false),form=ref({}),candidates=ref([]),history=ref([]),selected=ref({})
const fields={realName:'姓名',employeeNo:'工号',contactPhone:'电话',jobTitle:'岗位'},states={ACTIVE:'在职',LEFT:'离职',VALID:'平台记录有效',EXPIRED:'已到期',NOT_STARTED:'尚未开始',REVOKED:'已撤销',INACTIVE:'未授权',NOT_CONNECTED:'未连接设备'}
const labels={id:'编号',company_id:'企业编号',user_id:'账号编号',real_name:'姓名',employee_no:'工号',job_title:'岗位',contact_phone:'电话',status:'状态',record_state:'记录状态',entry_date:'入职日期',leave_date:'离职日期',device_code:'门禁点编号',valid_from:'开始时间',valid_to:'截止时间',sync_status:'设备同步',version:'版本',create_by:'创建人',create_time:'创建时间',update_by:'更新人',update_time:'更新时间',remark:'备注',last_error:'同步错误'}
async function load(){loading.value=true;try{const r=await request({url:access.value?'/personnel/access':'/personnel',params:{keyword:keyword.value,status:status.value,pageNum:page.value,pageSize:size.value}});rows.value=r.data.rows;total.value=r.data.total;if(!access.value)stats.value=(await request({url:'/personnel/stats'})).data}finally{loading.value=false}}
async function edit(row){form.value=row?{id:row.id,userId:row.user_id,realName:row.real_name,employeeNo:row.employee_no,contactPhone:row.contact_phone,jobTitle:row.job_title,deviceCode:row.device_code,validFrom:String(row.valid_from||'').replace(' ','T'),validTo:String(row.valid_to||'').replace(' ','T'),version:row.version,reason:''}:{reason:''};if(access.value)candidates.value=(await request({url:'/personnel',params:{status:'ACTIVE',pageSize:100}})).data.rows;else if(!row)candidates.value=(await request({url:'/personnel/candidates'})).data;visible.value=true}
async function searchPeople(keyword){if(access.value)candidates.value=(await request({url:"/personnel",params:{status:"ACTIVE",pageSize:100,keyword}})).data.rows}
async function save(){if(!form.value.reason?.trim()){ElMessage.warning('请填写原因');return}saving.value=true;try{const base=access.value?'/personnel/access':'/personnel';await request({url:base+(form.value.id?'/'+form.value.id:''),method:form.value.id?'put':'post',data:access.value?form.value:{userId:form.value.userId,data:form.value,reason:form.value.reason}});visible.value=false;ElMessage.success('已保存');await load()}finally{saving.value=false}}
async function change(row){try{const r=await ElMessageBox.prompt(access.value?'请输入撤销原因':'确认办理离职？未结束任务须先交接。请输入原因','变更确认',{inputPattern:/\S+/,inputErrorMessage:'原因必填'});await request({url:access.value?`/personnel/access/${row.id}/revoke`:`/personnel/${row.id}/leave`,method:'post',data:{version:row.version,reason:r.value}});ElMessage.success('已处理');await load()}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
async function view(row){selected.value=row;history.value=(await request({url:`/personnel/history/${access.value?'ACCESS':'EMPLOYEE'}/${row.id}`})).data;historyVisible.value=true}
async function exportData(){const blob=await request({url:'/personnel/export',params:{keyword:keyword.value,status:status.value},responseType:'blob'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='人员档案.csv';a.click();URL.revokeObjectURL(url)}
watch(access,()=>{page.value=1;rows.value=[];visible.value=false;historyVisible.value=false;load()},{immediate:true})
</script>
